<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('admin');if($_SERVER['REQUEST_METHOD']==='POST'){csrfCheck();$id=(int)$_POST['id'];$act=$_POST['aksi'];$reason=trim($_POST['alasan']??'');$map=['sembunyikan'=>'disembunyikan','pulihkan'=>'aktif','tinjau'=>'ditinjau'];if(isset($map[$act])){$st=$map[$act];$s=$koneksi->prepare('UPDATE laporan SET moderation_status=? WHERE id_laporan=?');$s->bind_param('si',$st,$id);$s->execute();$admin=(int)currentUser()['id_user'];$s=$koneksi->prepare('INSERT INTO moderasi_laporan(id_laporan,id_admin,tindakan,alasan) VALUES(?,?,?,?)');$s->bind_param('iiss',$id,$admin,$act,$reason);$s->execute();flash('Moderasi laporan diperbarui.');}redirect('admin/moderasi.php');}$pageTitle='Moderasi';$rows=$koneksi->query('SELECT l.id_laporan,l.nama_barang,l.moderation_status,l.jenis_laporan,u.nama FROM laporan l JOIN users u ON u.id_user=l.id_user ORDER BY l.created_at DESC');require __DIR__.'/../includes/header.php';?><div class="panel"><h2>Moderasi konten laporan</h2><div class="table-wrap"><table><tr><th>Laporan</th><th>Pelapor</th><th>Jenis</th><th>Status moderasi</th><th>Tindakan</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['nama_barang'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['jenis_laporan'])?></td><td><span class="badge <?=e($r['moderation_status'])?>"><?=e($r['moderation_status'])?></span></td><td><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="id" value="<?=$r['id_laporan']?>"><input name="alasan" class="search" placeholder="Alasan" style="width:110px;padding:7px"><button class="btn danger sm" name="aksi" value="sembunyikan">Sembunyikan</button><button class="btn success sm" name="aksi" value="pulihkan">Pulihkan</button></form></td></tr><?php endwhile;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
